def main():
    inherited=json.loads((AUDIT/'LOW_ILLUSION_SPELL_SOURCE_PREPARATION.json').read_text(encoding='utf-8'));protected=deepcopy(inherited['protectedFiles']);assert all(sha(GAME/p)==h for p,h in protected.items())
    def read(path):protected[path.relative_to(GAME).as_posix()]=sha(path);return json.loads(path.read_text(encoding='utf-8-sig'))
    catalog=read(ROOT/'data/public/spell_playtests/catalog.json');rows=catalog['spells'];by={r['id']:r for r in rows}
    selected=[r for r in rows if r['operational'] is None and r['schools'][0]!='Evocation' and min(v['rank'] for v in r['classAccess'].values())==3]
    assert len(selected)==21 and {r['id'] for r in selected}==set(QUESTIONS)
    source=read(ROOT/'data/playtest/spell_sources/catalog.json');core=read(ROOT/'data/public/Decennium_Descent_Core_Systems_Data_v2_Known_Descent.json');book=current_book_rows();bindings=[];differences=[]
    for row in selected:
        assert row['source']['original']==source[row['id']]
